import { TouchableOpacity, View, type ImageStyle } from 'react-native'
import { Image, ImageSource } from 'expo-image'
import React from 'react'
import { colors, Theme, useTheme } from '@/theme'
import { type Organization } from '@/screens/profile/ProfileScreen'
import { getBlurhashFromUUID } from '@/utils/getBlurhashFromUUID'
import { defineStyles } from '@/utils/defineStyles'
import { useOrganizationStore } from '@/stores/organizationStore'
import { router } from 'expo-router'
import * as Haptics from 'expo-haptics'
import { SettingsSectionTitle } from '../../../components/primitives/SettingsSectionTitle'
import { Text } from 'react-native'

type TeamsSectionProps = {
	teams: Organization[]
}

type MemoizedImageProps = {
	source: ImageSource
	style: ImageStyle
}

const MemoizedImage = React.memo(({ source, style }: MemoizedImageProps) => (
	<Image source={source} style={style} />
))

MemoizedImage.displayName = 'MemoizedImage'

export const TeamsSection = ({ teams }: TeamsSectionProps) => {
	const { theme } = useTheme()
	const { currentOrganizationIndex, setCurrentOrganizationIndex } =
		useOrganizationStore()

	const handleOrganizationPress = (originalIndex: number) => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
		setCurrentOrganizationIndex(originalIndex)
		router.back()
	}

	const reorderedTeams = (() => {
		if (
			currentOrganizationIndex >= 0 &&
			currentOrganizationIndex < teams.length
		) {
			const currentTeam = teams[currentOrganizationIndex]
			const otherTeams = teams.filter(
				(_, index) => index !== currentOrganizationIndex
			)
			return [currentTeam, ...otherTeams]
		}
		return teams
	})()

	return (
		<View style={styles.organizationContainer}>
			<SettingsSectionTitle title="Your teams" />
			<View style={styles.organizationItemsContainer}>
				{reorderedTeams.map((team) => {
					const imgSrc = team.logoUrl
					const originalIndex = teams.findIndex((t) => t.id === team.id)
					const isCurrentTeam = originalIndex === currentOrganizationIndex

					return (
						<TouchableOpacity
							key={team.id}
							style={[
								styles.organizationItemContainer,
								isCurrentTeam && styles.organizationItemContainerActive
							]}
							onPress={() => handleOrganizationPress(originalIndex)}
						>
							<View style={styles.organizationItemImageContainer}>
								<Image
									source={
										imgSrc
											? { uri: imgSrc }
											: {
													blurhash: getBlurhashFromUUID(team.id)
											  }
									}
									placeholder={{ blurhash: getBlurhashFromUUID(team.id) }}
									style={styles.organizationImage}
								/>
								<Text style={styles.organizationItemInitial}>
									{team.name.slice(0, 1)}
								</Text>
							</View>
							<Text style={styles.organizationItemName(theme)}>
								{team.name}
							</Text>
						</TouchableOpacity>
					)
				})}
			</View>
		</View>
	)
}

const styles = defineStyles({
	organizationContainer: {
		gap: 20
	},
	organizationItemsContainer: {
		gap: 18
	},
	organizationItemContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 20,
		opacity: 0.5
	},
	organizationItemImageContainer: {
		width: 44,
		height: 44,
		alignItems: 'center',
		justifyContent: 'center'
	},
	organizationImage: {
		width: 44,
		height: 44,
		borderRadius: 50,
		position: 'absolute'
	},
	organizationItemInitial: {
		fontSize: 16,
		fontWeight: '500',
		color: colors.light.gray[25]
	},
	organizationItemName: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	organizationItemContainerActive: {
		opacity: 1
	}
})
